(async () => {
  const shardNumbers = [0, 1, 2, 3];
  let totalUnits = 0;

  for (const shard of shardNumbers) {
    const result = await tools.lumen_scan_log({shard});
    const entries = result.content.filter(b => b.type === 'text').map(b => b.text);

    for (const entry of entries) {
      if (entry.includes('PAID')) {
        const unitsMatch = entry.match(/units: (\d+)/);
        if (unitsMatch && unitsMatch[1]) {
          totalUnits += parseInt(unitsMatch[1], 10);
        }
      }
    }
  }

  return totalUnits;
})()

(async () => {
  const shardNumbers = [0, 1, 2, 3];
  let totalUnits = 0;

  for (const shard of shardNumbers) {
    try {
      const result = await tools.lumen_scan_log({shard});
      const entries = result.content.filter(b => b.type === 'text').map(b => b.text);

      for (const entry of entries) {
        if (entry.includes('PAID')) {
          const unitsMatch = entry.match(/units: (\d+)/);
          if (unitsMatch && unitsMatch[1]) {
            totalUnits += parseInt(unitsMatch[1], 10);
          }
        }
      }
    } catch (error) {
      console.error(`Error processing shard ${shard}:`, error);
    }
  }

  return totalUnits;
})()

